export default {"file":"passed-out-students.html","title":"Passed Out Students - Schoolix","htmlClass":"","bodyClass":"","body":"\r\n<div id=\"sxPageLoader\" class=\"sx-page-loader\" role=\"status\" aria-live=\"polite\">\r\n  <section class=\"dots-container\" aria-label=\"Loading page\">\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n  </section>\r\n</div>\r\n  <div class=\"container\">\r\n    <div class=\"top-bar\">\r\n      <div class=\"top-bar-left\">\r\n        <div class=\"icon-badge\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M20.25 7.5l-.625 10.632a2.25 2.25 0 01-2.247 2.118H6.622a2.25 2.25 0 01-2.247-2.118L3.75 7.5M10 11.25h4M3.375 7.5h17.25c.621 0 1.125-.504 1.125-1.125v-1.5c0-.621-.504-1.125-1.125-1.125H3.375c-.621 0-1.125.504-1.125 1.125v1.5c0 .621.504 1.125 1.125 1.125z\" />\r\n          </svg>\r\n        </div>\r\n        <div>\r\n          <div class=\"eyebrow\">\r\n            <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n              <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M16.5 10.5V6.75a4.5 4.5 0 10-9 0v3.75m-.75 11.25h10.5a2.25 2.25 0 002.25-2.25v-6.75a2.25 2.25 0 00-2.25-2.25H6.75a2.25 2.25 0 00-2.25 2.25v6.75a2.25 2.25 0 002.25 2.25z\" />\r\n            </svg>\r\n            Read Only Archive\r\n          </div>\r\n          <h1>Passed Out Students</h1>\r\n          <p class=\"subtitle\">Class 12 passout aur TC issued students ka year-wise permanent view</p>\r\n        </div>\r\n      </div>\r\n      <div class=\"actions\">\r\n        <a href=\"#/students.html\" class=\"btn btn-secondary\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M15 19.128a9.38 9.38 0 002.625.372 9.337 9.337 0 004.121-.952 4.125 4.125 0 00-7.533-2.493M15 19.128v-.003c0-1.113-.285-2.16-.786-3.07M15 19.128v.106A12.318 12.318 0 018.624 21c-2.331 0-4.512-.645-6.374-1.766l-.001-.109a6.375 6.375 0 0111.964-3.07M12 6.375a3.375 3.375 0 11-6.75 0 3.375 3.375 0 016.75 0zm8.25 2.25a2.625 2.625 0 11-5.25 0 2.625 2.625 0 015.25 0z\" />\r\n          </svg>\r\n          Active Students\r\n        </a>\r\n        <a href=\"#/admin-dashboard.html\" class=\"btn btn-primary\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M3.75 6A2.25 2.25 0 016 3.75h2.25A2.25 2.25 0 0110.5 6v2.25a2.25 2.25 0 01-2.25 2.25H6a2.25 2.25 0 01-2.25-2.25V6zM3.75 15.75A2.25 2.25 0 016 13.5h2.25a2.25 2.25 0 012.25 2.25V18a2.25 2.25 0 01-2.25 2.25H6A2.25 2.25 0 013.75 18v-2.25zM13.5 6a2.25 2.25 0 012.25-2.25H18A2.25 2.25 0 0120.25 6v2.25A2.25 2.25 0 0118 10.5h-2.25a2.25 2.25 0 01-2.25-2.25V6zM13.5 15.75a2.25 2.25 0 012.25-2.25H18a2.25 2.25 0 012.25 2.25V18A2.25 2.25 0 0118 20.25h-2.25A2.25 2.25 0 0113.5 18v-2.25z\" />\r\n          </svg>\r\n          Dashboard\r\n        </a>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"panel\">\r\n      <div class=\"filters\">\r\n        <div class=\"filter-group\">\r\n          <label>\r\n            <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n              <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z\" />\r\n            </svg>\r\n            Search\r\n          </label>\r\n          <div class=\"input-wrapper\">\r\n            <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n              <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z\" />\r\n            </svg>\r\n            <input type=\"text\" id=\"searchInput\" placeholder=\"Search by name, ID, phone, email...\" oninput=\"applyFilters()\">\r\n          </div>\r\n        </div>\r\n        <div class=\"filter-group\">\r\n          <label>\r\n            <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n              <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 012.25-2.25h13.5A2.25 2.25 0 0121 7.5v11.25m-18 0A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75m-18 0v-7.5A2.25 2.25 0 015.25 9h13.5A2.25 2.25 0 0121 11.25v7.5\" />\r\n            </svg>\r\n            Passout Year\r\n          </label>\r\n          <select id=\"yearFilter\" onchange=\"applyFilters()\">\r\n            <option value=\"\">All Years</option>\r\n          </select>\r\n        </div>\r\n        <div class=\"filter-group\">\r\n          <label>\r\n            <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n              <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M9.568 3H5.25A2.25 2.25 0 003 5.25v4.318c0 .597.237 1.17.659 1.591l9.581 9.581c.699.699 1.78.872 2.607.33a18.095 18.095 0 005.223-5.223c.542-.827.369-1.908-.33-2.607L11.16 3.66A2.25 2.25 0 009.568 3z\" />\r\n              <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M6 6h.008v.008H6V6z\" />\r\n            </svg>\r\n            Status\r\n          </label>\r\n          <select id=\"statusFilter\" onchange=\"applyFilters()\">\r\n            <option value=\"\">All Status</option>\r\n            <option value=\"Passed Out\">Passed Out</option>\r\n            <option value=\"TC Issued\">TC Issued</option>\r\n          </select>\r\n        </div>\r\n        <button class=\"btn btn-secondary\" onclick=\"resetFilters()\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M16.023 9.348h4.992v-.001M2.985 19.644v-4.992m0 0h4.992m-4.993 0l3.181 3.183a8.25 8.25 0 0013.803-3.7M4.031 9.865a8.25 8.25 0 0113.803-3.7l3.181 3.182m0-4.991v4.99\" />\r\n          </svg>\r\n          Reset\r\n        </button>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"stats\" id=\"statsGrid\">\r\n      <!-- Stats populated by JS -->\r\n    </div>\r\n\r\n    <div class=\"table-wrap\">\r\n      <div class=\"head\">\r\n        <div>\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M15.75 6a3.75 3.75 0 11-7.5 0 3.75 3.75 0 017.5 0zM4.501 20.118a7.5 7.5 0 0114.998 0A17.933 17.933 0 0112 21.75c-2.676 0-5.216-.584-7.499-1.632z\" />\r\n          </svg>\r\n          Student\r\n        </div>\r\n        <div>\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M15 9h3.75M15 12h3.75M15 15h3.75M4.5 19.5h15a2.25 2.25 0 002.25-2.25V6.75A2.25 2.25 0 0019.5 4.5h-15a2.25 2.25 0 00-2.25 2.25v10.5A2.25 2.25 0 004.5 19.5zm6-10.125a1.875 1.875 0 11-3.75 0 1.875 1.875 0 013.75 0zm1.294 6.336a6.721 6.721 0 01-3.17.789 6.721 6.721 0 01-3.168-.789 3.376 3.376 0 016.338 0z\" />\r\n          </svg>\r\n          ID / Roll\r\n        </div>\r\n        <div>\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M15 9h3.75M15 12h3.75M15 15h3.75M4.5 19.5h15a2.25 2.25 0 002.25-2.25V6.75A2.25 2.25 0 0019.5 4.5h-15a2.25 2.25 0 00-2.25 2.25v10.5A2.25 2.25 0 004.5 19.5z\" />\r\n          </svg>\r\n          SR No.\r\n        </div>\r\n        <div>\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M4.26 10.147a60.436 60.436 0 00-.491 6.347A48.627 48.627 0 0112 20.904a48.627 48.627 0 018.232-4.41 60.46 60.46 0 00-.491-6.347m-15.482 0a50.57 50.57 0 00-2.658-.813A59.905 59.905 0 0112 3.493a59.902 59.902 0 0110.399 5.84c-.896.248-1.783.52-2.658.814m-15.482 0A50.697 50.697 0 0112 13.489a50.702 50.702 0 017.74-3.342\" />\r\n          </svg>\r\n          Final Class\r\n        </div>\r\n        <div>\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M2.25 6.75c0 8.284 6.716 15 15 15h2.25a2.25 2.25 0 002.25-2.25v-1.372c0-.516-.351-.966-.852-1.091l-4.423-1.106c-.44-.11-.902.055-1.173.417l-.97 1.293c-.282.376-.769.542-1.21.38a12.035 12.035 0 01-7.143-7.143c-.162-.441.004-.928.38-1.21l1.293-.97c.363-.271.527-.734.417-1.173L6.963 3.102a1.125 1.125 0 00-1.091-.852H4.5A2.25 2.25 0 002.25 4.5v2.25z\" />\r\n          </svg>\r\n          Phone\r\n        </div>\r\n        <div>\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 012.25-2.25h13.5A2.25 2.25 0 0121 7.5v11.25m-18 0A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75m-18 0v-7.5A2.25 2.25 0 015.25 9h13.5A2.25 2.25 0 0121 11.25v7.5m-9-6h.008v.008H12v-.008zM12 15h.008v.008H12V15zm0 2.25h.008v.008H12v-.008zM9.75 15h.008v.008H9.75V15zm0 2.25h.008v.008H9.75v-.008zM7.5 15h.008v.008H7.5V15zm0 2.25h.008v.008H7.5v-.008zm6.75-4.5h.008v.008h-.008v-.008zm0 2.25h.008v.008h-.008V15zm0 2.25h.008v.008h-.008v-.008zm2.25-4.5h.008v.008H16.5v-.008zm0 2.25h.008v.008H16.5V15z\" />\r\n          </svg>\r\n          Year\r\n        </div>\r\n        <div>\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z\" />\r\n          </svg>\r\n          Status\r\n        </div>\r\n        <div>Action</div>\r\n      </div>\r\n      <div id=\"studentsList\">\r\n        <div class=\"loading-state\">\r\n          <div class=\"loading-spinner\"></div>\r\n          Loading passed out students...\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Detail Modal -->\r\n  <div class=\"modal\" id=\"detailModal\">\r\n    <div class=\"modal-card\">\r\n      <div class=\"modal-head\">\r\n        <div>\r\n          <h2 id=\"modalTitle\">\r\n            <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n              <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M15.75 6a3.75 3.75 0 11-7.5 0 3.75 3.75 0 017.5 0zM4.501 20.118a7.5 7.5 0 0114.998 0A17.933 17.933 0 0112 21.75c-2.676 0-5.216-.584-7.499-1.632z\" />\r\n            </svg>\r\n            Student Details\r\n          </h2>\r\n          <p>\r\n            <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n              <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M16.5 10.5V6.75a4.5 4.5 0 10-9 0v3.75m-.75 11.25h10.5a2.25 2.25 0 002.25-2.25v-6.75a2.25 2.25 0 00-2.25-2.25H6.75a2.25 2.25 0 00-2.25 2.25v6.75a2.25 2.25 0 002.25 2.25z\" />\r\n            </svg>\r\n            View only record. Editing is disabled for archived students.\r\n          </p>\r\n        </div>\r\n        <button class=\"btn-close\" onclick=\"closeDetails()\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M6 18L18 6M6 6l12 12\" />\r\n          </svg>\r\n          Close\r\n        </button>\r\n      </div>\r\n      <div class=\"modal-body\" id=\"modalBody\">\r\n        <!-- Modal content populated by JS -->\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <script type=\"module\">\r\n    import { initializeApp } from \"./firebase-compat.js\";\r\n    import { getFirestore, collection, getDocs } from \"./firebase-compat.js\";\r\n    import { getAuth, onAuthStateChanged } from \"./firebase-compat.js\";\r\n\r\n    const firebaseConfig = {\r\n       apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n      authDomain: \"schoolix-48107.firebaseapp.com\",\r\n      projectId: \"schoolix-48107\",\r\n      storageBucket: \"schoolix-48107.firebasestorage.app\",\r\n      messagingSenderId: \"133937954491\",\r\n      appId: \"1:133937954491:web:69d8064422617eb8c4339e\",\r\n      measurementId: \"G-EG23XE5Q0Z\"\r\n    };\r\n\r\n    const app = initializeApp(firebaseConfig);\r\n    const db = getFirestore(app);\r\n    const auth = getAuth(app);\r\n    let currentUser = null;\r\n    let allArchived = [];\r\n    let filteredArchived = [];\r\n    let activeDetailStudent = null;\r\n\r\n    const esc = (value) => String(value ?? \"\").replace(/[&<>\"']/g, (char) => ({\r\n      \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\"\r\n    }[char]));\r\n    const val = (value) => value === undefined || value === null || value === \"\" ? \"N/A\" : value;\r\n    const phoneOf = (s = {}) => s.fatherPhone || s.fatherMobile || s.motherPhone || s.motherMobile || s.phone || \"\";\r\n    const finalClassOf = (s = {}) => [s.finalClass || s.class, s.finalSection || s.section].filter(Boolean).join(\"-\") || \"N/A\";\r\n    const recordCount = (s = {}, key) => Array.isArray(s.records?.[key]) ? s.records[key].length : 0;\r\n    const monthOrder = [\"January\", \"February\", \"March\", \"April\", \"May\", \"June\", \"July\", \"August\", \"September\", \"October\", \"November\", \"December\"];\r\n    const formatCurrency = (value = 0) => `₹${Number(value || 0).toLocaleString(\"en-IN\")}`;\r\n\r\n    function archiveStatus(student = {}) {\r\n      return student.status || (student.tcIssued ? \"TC Issued\" : \"Passed Out\");\r\n    }\r\n\r\n    function archiveStatusText(student = {}) {\r\n      const base = archiveStatus(student);\r\n      return student.tcIssued && base !== \"TC Issued\" ? `${base} + TC Issued` : base;\r\n    }\r\n\r\n    function archiveStatusPills(student = {}) {\r\n      const base = archiveStatus(student);\r\n      const academicLabel = base === \"TC Issued\" && !student.passoutYear ? \"TC Only\" : base;\r\n      const academicClass = academicLabel === \"Passed Out\" ? \"promoted\" : \"neutral\";\r\n      const tcLabel = student.tcIssued ? \"TC Issued\" : \"TC Not Issued\";\r\n      const tcClass = student.tcIssued ? \"tc\" : \"neutral\";\r\n      const checkIcon = `<svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2.5\" stroke=\"currentColor\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M4.5 12.75l6 6 9-13.5\" /></svg>`;\r\n      return `\r\n        <div class=\"status-panel\">\r\n          <div class=\"status-line\">\r\n            <span class=\"status-label\">Academic</span>\r\n            <span class=\"pill ${academicClass}\">${academicLabel === \"Passed Out\" ? checkIcon : \"\"}${esc(academicLabel)}</span>\r\n          </div>\r\n          <div class=\"status-line\">\r\n            <span class=\"status-label\">TC</span>\r\n            <span class=\"pill ${tcClass}\">${student.tcIssued ? checkIcon : \"\"}${esc(tcLabel)}</span>\r\n          </div>\r\n        </div>\r\n      `;\r\n    }\r\n\r\n    function toDate(value) {\r\n      if (!value) return null;\r\n      if (value?.toDate) return value.toDate();\r\n      if (value?.seconds) return new Date(value.seconds * 1000);\r\n      if (value instanceof Date) return value;\r\n      const date = new Date(value);\r\n      return Number.isNaN(date.getTime()) ? null : date;\r\n    }\r\n\r\n    function formatDate(value) {\r\n      const date = toDate(value);\r\n      return date ? date.toLocaleDateString(\"en-IN\", { day: \"2-digit\", month: \"short\", year: \"numeric\" }) : val(value);\r\n    }\r\n\r\n    function getMonthName(value) {\r\n      if (monthOrder.includes(value)) return value;\r\n      const date = toDate(value);\r\n      return date ? monthOrder[date.getMonth()] : \"Other\";\r\n    }\r\n\r\n    function getYearValue(value, fallback = \"\") {\r\n      const date = toDate(value);\r\n      if (date) return String(date.getFullYear());\r\n      const years = String(value || fallback || \"\").match(/\\b(20\\d{2}|19\\d{2})\\b/g);\r\n      return years?.length ? years[years.length - 1] : \"No Year\";\r\n    }\r\n\r\n    function getSessionLabel(record = {}, fallback = \"No Session\") {\r\n      return record.session || record.academicSession || record.currentYear || record.sessionName || record.sessionId || fallback;\r\n    }\r\n\r\n    function getFeeAmounts(fee = {}) {\r\n      const total = Number(fee.originalAmount ?? fee.amount ?? 0);\r\n      const applied = Array.isArray(fee.payments)\r\n        ? fee.payments.reduce((sum, payment) => sum + Number(payment.appliedAmount ?? payment.amount ?? 0), 0)\r\n        : Number(fee.totalPaidAmount ?? fee.paidAmount ?? 0);\r\n      const extra = Number(fee.totalExtraPaidAmount ?? fee.extraAmount ?? 0);\r\n      const collected = Number(fee.totalCollectedAmount ?? applied + extra);\r\n      const due = Number.isFinite(Number(fee.remainingAmount))\r\n        ? Number(fee.remainingAmount)\r\n        : Math.max(0, total - applied);\r\n      return { total, applied, extra, collected, due: Math.max(0, due) };\r\n    }\r\n\r\n    function statusClass(value = \"\") {\r\n      const text = String(value).toLowerCase();\r\n      if (text.includes(\"present\") || text === \"paid\") return \"paid present\";\r\n      if (text.includes(\"half\") || text.includes(\"partial\")) return \"partial half\";\r\n      if (text.includes(\"absent\") || text.includes(\"unpaid\") || text.includes(\"imposed\") || text.includes(\"pending\")) return \"due absent\";\r\n      return \"\";\r\n    }\r\n\r\n    function groupBy(records, getKey) {\r\n      return records.reduce((map, record) => {\r\n        const key = getKey(record);\r\n        if (!map.has(key)) map.set(key, []);\r\n        map.get(key).push(record);\r\n        return map;\r\n      }, new Map());\r\n    }\r\n\r\n    function sortMonthKeys(keys) {\r\n      return [...keys].sort((a, b) => {\r\n        const [yearA, monthA] = a.split(\"::\");\r\n        const [yearB, monthB] = b.split(\"::\");\r\n        const yearDiff = Number(yearB || 0) - Number(yearA || 0);\r\n        if (yearDiff) return yearDiff;\r\n        return monthOrder.indexOf(monthA) - monthOrder.indexOf(monthB);\r\n      });\r\n    }\r\n\r\n    function uniqueOptions(records, getKey) {\r\n      return [...new Set(records.map(getKey).filter(Boolean))];\r\n    }\r\n\r\n    function monthKeyForRecord(record = {}) {\r\n      const source = record.date || record.timestamp || record.createdAt || record.updatedAt || record.month;\r\n      return `${getYearValue(source, getSessionLabel(record))}::${getMonthName(record.month || source)}`;\r\n    }\r\n\r\n    function renderSelectOptions(values, placeholder) {\r\n      return `<option value=\"\">${esc(placeholder)}</option>${values.map((value) => `<option value=\"${esc(value)}\">${esc(value.replace(\"::\", \" - \"))}</option>`).join(\"\")}`;\r\n    }\r\n\r\n    function getReportTermKey(report = {}) {\r\n      return report.termLabel || report.term || report.termKey || report.examName || report.title || \"Untitled Term\";\r\n    }\r\n\r\n    function renderReportControls(type, student = {}) {\r\n      const records = Array.isArray(student.records?.[type]) ? student.records[type] : [];\r\n      if (!records.length) return '<div class=\"report-empty\">No archived records found for this student.</div>';\r\n      const sessions = uniqueOptions(records, getSessionLabel).sort();\r\n      if (type === \"reportCards\") {\r\n        const terms = uniqueOptions(records, getReportTermKey).sort();\r\n        return `\r\n          <div class=\"report-controls\">\r\n            <div class=\"filter-group\">\r\n              <label>Result Session</label>\r\n              <select id=\"${type}SessionFilter\" onchange=\"renderArchivedReport('${type}')\">\r\n                ${renderSelectOptions(sessions, \"Select session\")}\r\n              </select>\r\n            </div>\r\n            <div class=\"filter-group\">\r\n              <label>Result Term</label>\r\n              <select id=\"${type}TermFilter\" onchange=\"renderArchivedReport('${type}')\">\r\n                ${renderSelectOptions(terms, \"Select term\")}\r\n              </select>\r\n            </div>\r\n          </div>\r\n          <div id=\"${type}ReportOutput\" class=\"report-empty\">Select session and term to view result history.</div>\r\n        `;\r\n      }\r\n      const months = sortMonthKeys(uniqueOptions(records, monthKeyForRecord));\r\n      const title = type === \"attendance\" ? \"Attendance History\" : \"Payment History\";\r\n      return `\r\n        <div class=\"report-controls\">\r\n          <div class=\"filter-group\">\r\n            <label>${title} Session</label>\r\n            <select id=\"${type}SessionFilter\" onchange=\"renderArchivedReport('${type}')\">\r\n              ${renderSelectOptions(sessions, \"Select session\")}\r\n            </select>\r\n          </div>\r\n          <div class=\"filter-group\">\r\n            <label>${title} Month</label>\r\n            <select id=\"${type}MonthFilter\" onchange=\"renderArchivedReport('${type}')\">\r\n              ${renderSelectOptions(months, \"Select month\")}\r\n            </select>\r\n          </div>\r\n        </div>\r\n        <div id=\"${type}ReportOutput\" class=\"report-empty\">Select session and month to view ${title.toLowerCase()}.</div>\r\n      `;\r\n    }\r\n\r\n    window.renderArchivedReport = (type) => {\r\n      if (!activeDetailStudent) return;\r\n      const output = document.getElementById(`${type}ReportOutput`);\r\n      const selectedSession = document.getElementById(`${type}SessionFilter`)?.value || \"\";\r\n      if (type === \"reportCards\") {\r\n        const selectedTerm = document.getElementById(`${type}TermFilter`)?.value || \"\";\r\n        if (!output) return;\r\n        if (!selectedSession || !selectedTerm) {\r\n          output.className = \"report-empty\";\r\n          output.innerHTML = \"Select session and term to view result history.\";\r\n          return;\r\n        }\r\n        const records = (activeDetailStudent.records?.reportCards || []).filter((record) =>\r\n          getSessionLabel(record) === selectedSession && getReportTermKey(record) === selectedTerm\r\n        );\r\n        output.className = \"\";\r\n        output.innerHTML = renderResultTable(records);\r\n        return;\r\n      }\r\n      const selectedMonth = document.getElementById(`${type}MonthFilter`)?.value || \"\";\r\n      if (!output) return;\r\n      if (!selectedSession || !selectedMonth) {\r\n        output.className = \"report-empty\";\r\n        output.innerHTML = `Select session and month to view ${type === \"attendance\" ? \"attendance history\" : \"payment history\"}.`;\r\n        return;\r\n      }\r\n      const records = (activeDetailStudent.records?.[type] || []).filter((record) =>\r\n        getSessionLabel(record) === selectedSession && monthKeyForRecord(record) === selectedMonth\r\n      );\r\n      output.className = \"\";\r\n      output.innerHTML = type === \"attendance\" ? renderAttendanceTable(records, selectedMonth) : renderFeesTable(records, selectedMonth);\r\n    };\r\n\r\n    function renderAttendanceTable(records = [], selectedMonth = \"\") {\r\n      if (!records.length) return '<div class=\"report-empty\">No attendance found for selected session and month.</div>';\r\n      const [year, month] = selectedMonth.split(\"::\");\r\n      const sorted = records.sort((a, b) => (toDate(a.date || a.timestamp || a.createdAt) || 0) - (toDate(b.date || b.timestamp || b.createdAt) || 0));\r\n      const counts = sorted.reduce((summary, record) => {\r\n        const status = String(record.status || \"Not Marked\");\r\n        if (status === \"Present\") summary.present += 1;\r\n        else if (status === \"Absent\") summary.absent += 1;\r\n        else if (status === \"Half Day\") summary.half += 1;\r\n        else summary.other += 1;\r\n        return summary;\r\n      }, { present: 0, absent: 0, half: 0, other: 0 });\r\n      const marked = counts.present + counts.absent + counts.half + counts.other;\r\n      const percentage = marked ? Math.round(((counts.present + counts.half * 0.5) / marked) * 100) : 0;\r\n      return `\r\n        <div class=\"report-section\">\r\n          <div class=\"report-head\">\r\n            <span>${esc(month)} ${esc(year)}</span>\r\n            <span>Present ${counts.present} | Half ${counts.half} | Absent ${counts.absent} | Attendance ${percentage}%</span>\r\n          </div>\r\n          <table class=\"report-table\">\r\n            <thead>\r\n              <tr><th>Date</th><th>Status</th><th>Class</th><th>Marked By</th><th>Remarks</th></tr>\r\n            </thead>\r\n            <tbody>\r\n              ${sorted.map((record) => `\r\n                <tr>\r\n                  <td>${esc(formatDate(record.date || record.timestamp || record.createdAt))}</td>\r\n                  <td><span class=\"status-chip ${statusClass(record.status)}\">${esc(record.status || \"Not Marked\")}</span></td>\r\n                  <td>${esc([record.class, record.section].filter(Boolean).join(\"-\") || \"N/A\")}</td>\r\n                  <td>${esc(record.markedBy || record.markedByRole || \"N/A\")}</td>\r\n                  <td>${esc(record.remarks || record.note || \"\")}</td>\r\n                </tr>\r\n              `).join(\"\")}\r\n            </tbody>\r\n          </table>\r\n        </div>\r\n      `;\r\n    }\r\n\r\n    function renderFeesTable(records = [], selectedMonth = \"\") {\r\n      if (!records.length) return '<div class=\"report-empty\">No fee/payment history found for selected session and month.</div>';\r\n      const [year, month] = selectedMonth.split(\"::\");\r\n      const sorted = records.sort((a, b) => (toDate(a.date || a.createdAt) || 0) - (toDate(b.date || b.createdAt) || 0));\r\n      const totals = sorted.reduce((sum, fee) => {\r\n        const amount = getFeeAmounts(fee);\r\n        sum.assigned += amount.total;\r\n        sum.applied += amount.applied;\r\n        sum.extra += amount.extra;\r\n        sum.due += amount.due;\r\n        return sum;\r\n      }, { assigned: 0, applied: 0, extra: 0, due: 0 });\r\n      return `\r\n        <div class=\"report-section\">\r\n          <div class=\"report-head\">\r\n            <span>${esc(month)} ${esc(year)}</span>\r\n            <span>Assigned ${formatCurrency(totals.assigned)} | Paid ${formatCurrency(totals.applied)} | Due ${formatCurrency(totals.due)}</span>\r\n          </div>\r\n          <table class=\"report-table\">\r\n            <thead>\r\n              <tr><th>Month</th><th>Assigned</th><th>Paid / Applied</th><th>Extra</th><th>Due</th><th>Status</th><th>Payments</th></tr>\r\n            </thead>\r\n            <tbody>\r\n              ${sorted.map((fee) => {\r\n                const amount = getFeeAmounts(fee);\r\n                const payments = Array.isArray(fee.payments) && fee.payments.length\r\n                  ? fee.payments.map((payment) => `${esc(formatDate(payment.date))}: ${formatCurrency(payment.receivedAmount ?? payment.fullAmount ?? payment.amount ?? 0)} received, ${formatCurrency(payment.appliedAmount ?? payment.amount ?? 0)} applied`).join(\"<br>\")\r\n                  : \"No payment history\";\r\n                return `\r\n                  <tr>\r\n                    <td>${esc(fee.month || \"N/A\")}<br><small style=\"color:var(--slate-500)\">${esc(formatDate(fee.date || fee.createdAt || fee.updatedAt))}</small></td>\r\n                    <td class=\"money\">${formatCurrency(amount.total)}</td>\r\n                    <td class=\"money\">${formatCurrency(amount.applied)}</td>\r\n                    <td class=\"money\">${formatCurrency(amount.extra)}</td>\r\n                    <td class=\"money\">${formatCurrency(amount.due)}</td>\r\n                    <td><span class=\"status-chip ${statusClass(fee.status)}\">${esc(fee.status || \"Pending\")}</span></td>\r\n                    <td>${payments}</td>\r\n                  </tr>\r\n                `;\r\n              }).join(\"\")}\r\n            </tbody>\r\n          </table>\r\n        </div>\r\n      `;\r\n    }\r\n\r\n    function renderResultTable(records = []) {\r\n      if (!records.length) return '<div class=\"report-empty\">No result/report card found for selected session and term.</div>';\r\n      const sorted = records.sort((a, b) => (toDate(b.createdAt || b.generatedAt || b.updatedAt) || 0) - (toDate(a.createdAt || a.generatedAt || a.updatedAt) || 0));\r\n      return sorted.map((report) => {\r\n        const subjects = Array.isArray(report.subjects) ? report.subjects : [];\r\n        const totalObtained = report.totalMarks ?? report.obtainedMarks ?? subjects.reduce((sum, sub) => sum + Number(sub.obtained ?? sub.obtainedMarks ?? sub.marks ?? 0), 0);\r\n        const totalMax = report.totalMaxMarks ?? report.maxMarks ?? subjects.reduce((sum, sub) => sum + Number(sub.maxMarks ?? sub.totalMarks ?? 0), 0);\r\n        const percentage = report.percentage ?? (Number(totalMax) ? ((Number(totalObtained) / Number(totalMax)) * 100).toFixed(2) : \"\");\r\n        return `\r\n          <div class=\"report-section\">\r\n            <div class=\"report-head\">\r\n              <span>${esc(getReportTermKey(report))}</span>\r\n              <span>Percentage ${esc(percentage || \"N/A\")}% | Grade ${esc(report.grade || \"N/A\")}</span>\r\n            </div>\r\n            <div class=\"detail-grid\" style=\"padding:16px;background:var(--slate-50)\">\r\n              ${field(\"Session\", getSessionLabel(report))}\r\n              ${field(\"Generated\", formatDate(report.createdAt || report.generatedAt || report.updatedAt))}\r\n              ${field(\"Total Marks\", `${totalObtained || \"N/A\"} / ${totalMax || \"N/A\"}`)}\r\n              ${field(\"Rank\", report.rank)}\r\n              ${field(\"Remarks\", report.remarks || report.teacherRemarks || report.resultRemarks)}\r\n            </div>\r\n            <table class=\"report-table\">\r\n              <thead>\r\n                <tr><th>Subject</th><th>Obtained</th><th>Max</th><th>Grade</th><th>Remarks</th></tr>\r\n              </thead>\r\n              <tbody>\r\n                ${subjects.length ? subjects.map((sub) => `\r\n                  <tr>\r\n                    <td>${esc(sub.name || sub.subject || \"Subject\")}</td>\r\n                    <td>${esc(sub.obtained ?? sub.obtainedMarks ?? sub.marks ?? \"N/A\")}</td>\r\n                    <td>${esc(sub.maxMarks ?? sub.totalMarks ?? \"N/A\")}</td>\r\n                    <td>${esc(sub.grade || \"N/A\")}</td>\r\n                    <td>${esc(sub.remarks || \"\")}</td>\r\n                  </tr>\r\n                `).join(\"\") : '<tr><td colspan=\"5\" style=\"text-align:center;color:var(--slate-500)\">No subject details saved in this report.</td></tr>'}\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n        `;\r\n      }).join(\"\");\r\n    }\r\n\r\n    function searchableText(student = {}) {\r\n      return [\r\n        student.name, student.studentName, student.studentId, student.roll, student.email,\r\n        student.parentEmail, student.father, student.mother, student.fatherPhone,\r\n        student.motherPhone, student.phone, student.passoutYear, student.tcNumber,\r\n        student.srNumber, student.category, student.gender, student.aadharNumber,\r\n        student.archiveReason, archiveStatusText(student), student.tcIssued ? \"tc issued\" : \"tc not issued\", finalClassOf(student)\r\n      ].join(\" \").toLowerCase();\r\n    }\r\n\r\n    function populateYears() {\r\n      const select = document.getElementById(\"yearFilter\");\r\n      const years = [...new Set(allArchived.map((s) => s.passoutYear).filter(Boolean))]\r\n        .sort((a, b) => Number(b) - Number(a));\r\n      select.innerHTML = '<option value=\"\">All Years</option>' + years.map((year) => `<option value=\"${esc(year)}\">${esc(year)}</option>`).join(\"\");\r\n    }\r\n\r\n    function updateStats(students = filteredArchived) {\r\n      const years = new Set(students.map((s) => s.passoutYear).filter(Boolean));\r\n      const tc = students.filter((s) => s.tcIssued || archiveStatus(s) === \"TC Issued\").length;\r\n      const passed = students.filter((s) => archiveStatus(s) === \"Passed Out\").length;\r\n      document.getElementById(\"statsGrid\").innerHTML = `\r\n        <div class=\"stat\">\r\n          <div class=\"stat-header\">\r\n            <div class=\"stat-icon blue\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M15 19.128a9.38 9.38 0 002.625.372 9.337 9.337 0 004.121-.952 4.125 4.125 0 00-7.533-2.493M15 19.128v-.003c0-1.113-.285-2.16-.786-3.07M15 19.128v.106A12.318 12.318 0 018.624 21c-2.331 0-4.512-.645-6.374-1.766l-.001-.109a6.375 6.375 0 0111.964-3.07M12 6.375a3.375 3.375 0 11-6.75 0 3.375 3.375 0 016.75 0zm8.25 2.25a2.625 2.625 0 11-5.25 0 2.625 2.625 0 015.25 0z\" />\r\n              </svg>\r\n            </div>\r\n          </div>\r\n          <strong>${students.length}</strong>\r\n          <span>Visible Records</span>\r\n        </div>\r\n        <div class=\"stat\">\r\n          <div class=\"stat-header\">\r\n            <div class=\"stat-icon green\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 012.25-2.25h13.5A2.25 2.25 0 0121 7.5v11.25m-18 0A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75m-18 0v-7.5A2.25 2.25 0 015.25 9h13.5A2.25 2.25 0 0121 11.25v7.5\" />\r\n              </svg>\r\n            </div>\r\n          </div>\r\n          <strong>${years.size}</strong>\r\n          <span>Passout Years</span>\r\n        </div>\r\n        <div class=\"stat\">\r\n          <div class=\"stat-header\">\r\n            <div class=\"stat-icon orange\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M4.26 10.147a60.436 60.436 0 00-.491 6.347A48.627 48.627 0 0112 20.904a48.627 48.627 0 018.232-4.41 60.46 60.46 0 00-.491-6.347m-15.482 0a50.57 50.57 0 00-2.658-.813A59.905 59.905 0 0112 3.493a59.902 59.902 0 0110.399 5.84c-.896.248-1.783.52-2.658.814m-15.482 0A50.697 50.697 0 0112 13.489a50.702 50.702 0 017.74-3.342\" />\r\n              </svg>\r\n            </div>\r\n          </div>\r\n          <strong>${passed}</strong>\r\n          <span>Class 12 Passout</span>\r\n        </div>\r\n        <div class=\"stat\">\r\n          <div class=\"stat-header\">\r\n            <div class=\"stat-icon red\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m0 12.75h7.5m-7.5 3H12M10.5 2.25H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z\" />\r\n              </svg>\r\n            </div>\r\n          </div>\r\n          <strong>${tc}</strong>\r\n          <span>TC Issued</span>\r\n        </div>\r\n      `;\r\n    }\r\n\r\n    function renderStudents(students = filteredArchived) {\r\n      updateStats(students);\r\n      const target = document.getElementById(\"studentsList\");\r\n      if (!students.length) {\r\n        target.innerHTML = `\r\n          <div class=\"empty\">\r\n            <div class=\"empty-icon\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"1.5\" stroke=\"currentColor\">\r\n                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M20.25 7.5l-.625 10.632a2.25 2.25 0 01-2.247 2.118H6.622a2.25 2.25 0 01-2.247-2.118L3.75 7.5m6 4.125l2.25 2.25m0 0l2.25 2.25M12 13.875l2.25-2.25M12 13.875l-2.25 2.25M3.375 7.5h17.25c.621 0 1.125-.504 1.125-1.125v-1.5c0-.621-.504-1.125-1.125-1.125H3.375c-.621 0-1.125.504-1.125 1.125v1.5c0 .621.504 1.125 1.125 1.125z\" />\r\n              </svg>\r\n            </div>\r\n            No archived students found for selected filters.\r\n          </div>\r\n        `;\r\n        return;\r\n      }\r\n      target.innerHTML = students.map((s) => {\r\n        return `\r\n          <div class=\"row\">\r\n            <div class=\"student-cell\" data-label=\"Student\">\r\n              <div class=\"avatar\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"1.5\" stroke=\"currentColor\">\r\n                  <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M15.75 6a3.75 3.75 0 11-7.5 0 3.75 3.75 0 017.5 0zM4.501 20.118a7.5 7.5 0 0114.998 0A17.933 17.933 0 0112 21.75c-2.676 0-5.216-.584-7.499-1.632z\" />\r\n                </svg>\r\n              </div>\r\n              <div>\r\n                <div class=\"name\">${esc(s.name || s.studentName || \"N/A\")}</div>\r\n                <div class=\"muted\">\r\n                  <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n                    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M21.75 6.75v10.5a2.25 2.25 0 01-2.25 2.25h-15a2.25 2.25 0 01-2.25-2.25V6.75m19.5 0A2.25 2.25 0 0019.5 4.5h-15a2.25 2.25 0 00-2.25 2.25m19.5 0v.243a2.25 2.25 0 01-1.07 1.916l-7.5 4.615a2.25 2.25 0 01-2.36 0L3.32 8.91a2.25 2.25 0 01-1.07-1.916V6.75\" />\r\n                  </svg>\r\n                  ${esc(s.email || s.parentEmail || \"No email\")}\r\n                </div>\r\n              </div>\r\n            </div>\r\n            <div class=\"id-cell\" data-label=\"ID / Roll\">\r\n              <span class=\"id-value\">${esc(s.studentId || s.id || \"N/A\")}</span>\r\n              <span class=\"roll-value\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n                  <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M5.25 8.25h15m-16.5 7.5h15m-1.8-13.5l-3.9 19.5m-2.1-19.5l-3.9 19.5\" />\r\n                </svg>\r\n                Roll ${esc(s.roll || \"-\")}\r\n              </span>\r\n            </div>\r\n            <div class=\"id-cell\" data-label=\"SR No.\">\r\n              <span class=\"id-value\">${esc(s.srNumber || \"N/A\")}</span>\r\n              <span class=\"roll-value\">School record</span>\r\n            </div>\r\n            <div data-label=\"Final Class\">\r\n              <span class=\"class-badge\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n                  <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M4.26 10.147a60.436 60.436 0 00-.491 6.347A48.627 48.627 0 0112 20.904a48.627 48.627 0 018.232-4.41 60.46 60.46 0 00-.491-6.347m-15.482 0a50.57 50.57 0 00-2.658-.813A59.905 59.905 0 0112 3.493a59.902 59.902 0 0110.399 5.84c-.896.248-1.783.52-2.658.814m-15.482 0A50.697 50.697 0 0112 13.489a50.702 50.702 0 017.74-3.342\" />\r\n                </svg>\r\n                ${esc(finalClassOf(s))}\r\n              </span>\r\n            </div>\r\n            <div data-label=\"Phone\">\r\n              <span class=\"phone-value\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n                  <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M2.25 6.75c0 8.284 6.716 15 15 15h2.25a2.25 2.25 0 002.25-2.25v-1.372c0-.516-.351-.966-.852-1.091l-4.423-1.106c-.44-.11-.902.055-1.173.417l-.97 1.293c-.282.376-.769.542-1.21.38a12.035 12.035 0 01-7.143-7.143c-.162-.441.004-.928.38-1.21l1.293-.97c.363-.271.527-.734.417-1.173L6.963 3.102a1.125 1.125 0 00-1.091-.852H4.5A2.25 2.25 0 002.25 4.5v2.25z\" />\r\n                </svg>\r\n                ${esc(phoneOf(s) || \"N/A\")}\r\n              </span>\r\n            </div>\r\n            <div data-label=\"Year\">\r\n              <span class=\"year-badge\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n                  <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 012.25-2.25h13.5A2.25 2.25 0 0121 7.5v11.25m-18 0A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75m-18 0v-7.5A2.25 2.25 0 015.25 9h13.5A2.25 2.25 0 0121 11.25v7.5\" />\r\n                </svg>\r\n                ${esc(s.passoutYear || \"N/A\")}\r\n              </span>\r\n            </div>\r\n            <div data-label=\"Status\">${archiveStatusPills(s)}</div>\r\n            <div data-label=\"Action\">\r\n              <button class=\"btn-view\" onclick=\"showDetails('${esc(s.id)}')\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n                  <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M2.036 12.322a1.012 1.012 0 010-.639C3.423 7.51 7.36 4.5 12 4.5c4.638 0 8.573 3.007 9.963 7.178.07.207.07.431 0 .639C20.577 16.49 16.64 19.5 12 19.5c-4.638 0-8.573-3.007-9.963-7.178z\" />\r\n                  <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M15 12a3 3 0 11-6 0 3 3 0 016 0z\" />\r\n                </svg>\r\n                View\r\n              </button>\r\n            </div>\r\n          </div>\r\n        `;\r\n      }).join(\"\");\r\n    }\r\n\r\n    window.applyFilters = () => {\r\n      const queryText = document.getElementById(\"searchInput\").value.trim().toLowerCase();\r\n      const year = document.getElementById(\"yearFilter\").value;\r\n      const status = document.getElementById(\"statusFilter\").value;\r\n      filteredArchived = allArchived.filter((student) => {\r\n        const actualStatus = archiveStatus(student);\r\n        const matchesSearch = !queryText || searchableText(student).includes(queryText);\r\n        const matchesYear = !year || String(student.passoutYear || \"\") === year;\r\n        const matchesStatus = !status || actualStatus === status || (status === \"TC Issued\" && student.tcIssued);\r\n        return matchesSearch && matchesYear && matchesStatus;\r\n      });\r\n      renderStudents(filteredArchived);\r\n    };\r\n\r\n    window.resetFilters = () => {\r\n      document.getElementById(\"searchInput\").value = \"\";\r\n      document.getElementById(\"yearFilter\").value = \"\";\r\n      document.getElementById(\"statusFilter\").value = \"\";\r\n      window.applyFilters();\r\n    };\r\n\r\n    function field(label, value, icon = \"\") {\r\n      return `<div class=\"field\"><span>${icon}${esc(label)}</span><strong>${esc(val(value))}</strong></div>`;\r\n    }\r\n\r\n    window.showDetails = (id) => {\r\n      const student = allArchived.find((entry) => entry.id === id);\r\n      if (!student) return;\r\n      activeDetailStudent = student;\r\n      const tc = student.transferCertificate || {};\r\n      document.getElementById(\"modalTitle\").innerHTML = `\r\n        <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n          <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M15.75 6a3.75 3.75 0 11-7.5 0 3.75 3.75 0 017.5 0zM4.501 20.118a7.5 7.5 0 0114.998 0A17.933 17.933 0 0112 21.75c-2.676 0-5.216-.584-7.499-1.632z\" />\r\n        </svg>\r\n        ${esc(student.name || student.studentName || \"Student\")} (${esc(student.passoutYear || \"N/A\")})\r\n      `;\r\n      document.getElementById(\"modalBody\").innerHTML = `\r\n        <div class=\"detail-grid\">\r\n          ${field(\"Name\", student.name || student.studentName)}\r\n          ${field(\"Student ID\", student.studentId)}\r\n          ${field(\"SR Number\", student.srNumber)}\r\n          ${field(\"Roll\", student.roll)}\r\n          ${field(\"Final Class\", finalClassOf(student))}\r\n          ${field(\"Passout Year\", student.passoutYear)}\r\n          ${field(\"Academic Status\", archiveStatus(student))}\r\n          ${field(\"TC Status\", student.tcIssued ? \"TC Issued\" : \"TC Not Issued\")}\r\n          ${field(\"Archive Reason\", student.archiveReason)}\r\n          ${field(\"Result %\", student.resultPercentage)}\r\n          ${field(\"Gender\", student.gender)}\r\n          ${field(\"Category\", student.category)}\r\n          ${field(\"Blood Group\", student.bloodGroup)}\r\n          ${field(\"Religion\", student.religion)}\r\n          ${field(\"Previous School\", student.previousSchool)}\r\n          ${field(\"Father\", student.father)}\r\n          ${field(\"Father Phone\", student.fatherPhone || student.fatherMobile)}\r\n          ${field(\"Father Email\", student.fatherEmail)}\r\n          ${field(\"Mother\", student.mother)}\r\n          ${field(\"Mother Phone\", student.motherPhone || student.motherMobile)}\r\n          ${field(\"Mother Email\", student.motherEmail)}\r\n          ${field(\"Phone\", student.phone)}\r\n          ${field(\"Email\", student.email)}\r\n          ${field(\"Parent Email\", student.parentEmail || student.fatherEmail || student.motherEmail)}\r\n          ${field(\"Admission Year\", student.yearOfAdmission)}\r\n          ${field(\"Admission Date\", student.admissionDate || student.dateOfAdmission)}\r\n          ${field(\"Current/Archive Session\", student.currentYear || student.academicSession || student.session)}\r\n          ${field(\"DOB\", student.dob)}\r\n          ${field(\"Aadhaar\", student.aadharNumber)}\r\n          ${field(\"Address\", student.address)}\r\n          ${field(\"Documents\", student.documentList || student.documents)}\r\n          ${field(\"Photo URL\", student.photoUrl || student.imageUrl || student.profilePhotoUrl)}\r\n        </div>\r\n        <h3 class=\"section-title\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m0 12.75h7.5m-7.5 3H12M10.5 2.25H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z\" />\r\n          </svg>\r\n          Transfer Certificate\r\n        </h3>\r\n        <div class=\"detail-grid\">\r\n          ${field(\"TC Number\", student.tcNumber || tc.tcNumber)}\r\n          ${field(\"Leaving Date\", tc.leavingDate)}\r\n          ${field(\"Reason\", tc.reason)}\r\n          ${field(\"Conduct\", tc.conduct)}\r\n        </div>\r\n        <h3 class=\"section-title\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M3.75 9.776c.112-.017.227-.026.344-.026h15.812c.117 0 .232.009.344.026m-16.5 0a2.25 2.25 0 00-1.883 2.542l.857 6a2.25 2.25 0 002.227 1.932H19.05a2.25 2.25 0 002.227-1.932l.857-6a2.25 2.25 0 00-1.883-2.542m-16.5 0V6A2.25 2.25 0 016 3.75h3.879a1.5 1.5 0 011.06.44l2.122 2.12a1.5 1.5 0 001.06.44H18A2.25 2.25 0 0120.25 9v.776\" />\r\n          </svg>\r\n          Saved Record Counts\r\n        </h3>\r\n        <div class=\"detail-grid\">\r\n          ${field(\"Attendance Records\", recordCount(student, \"attendance\"))}\r\n          ${field(\"Fee Records\", recordCount(student, \"fees\"))}\r\n          ${field(\"Report Cards\", recordCount(student, \"reportCards\"))}\r\n        </div>\r\n        <h3 class=\"section-title\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z\" />\r\n          </svg>\r\n          Attendance History\r\n        </h3>\r\n        ${renderReportControls(\"attendance\", student)}\r\n        <h3 class=\"section-title\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M2.25 18.75a60.07 60.07 0 0115.797 2.101c.727.198 1.453-.342 1.453-1.096V18.75M3.75 4.5v.75A.75.75 0 013 6h-.75m0 0v-.375c0-.621.504-1.125 1.125-1.125H20.25M2.25 6v9m18-10.5v.75c0 .414.336.75.75.75h.75m-1.5-1.5h.375c.621 0 1.125.504 1.125 1.125v9.75c0 .621-.504 1.125-1.125 1.125h-.375m1.5-1.5H21a.75.75 0 00-.75.75v.75m0 0H3.75m0 0h-.375a1.125 1.125 0 01-1.125-1.125V15m1.5 1.5v-.75A.75.75 0 003 15h-.75M15 10.5a3 3 0 11-6 0 3 3 0 016 0zm3 0h.008v.008H18V10.5zm-12 0h.008v.008H6V10.5z\" />\r\n          </svg>\r\n          Payment History\r\n        </h3>\r\n        ${renderReportControls(\"fees\", student)}\r\n        <h3 class=\"section-title\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M4.26 10.147a60.436 60.436 0 00-.491 6.347A48.627 48.627 0 0112 20.904a48.627 48.627 0 018.232-4.41 60.46 60.46 0 00-.491-6.347m-15.482 0a50.57 50.57 0 00-2.658-.813A59.905 59.905 0 0112 3.493a59.902 59.902 0 0110.399 5.84c-.896.248-1.783.52-2.658.814m-15.482 0A50.697 50.697 0 0112 13.489a50.702 50.702 0 017.74-3.342\" />\r\n          </svg>\r\n          Result History\r\n        </h3>\r\n        ${renderReportControls(\"reportCards\", student)}\r\n      `;\r\n      document.getElementById(\"detailModal\").classList.add(\"open\");\r\n    };\r\n\r\n    window.closeDetails = () => {\r\n      activeDetailStudent = null;\r\n      document.getElementById(\"detailModal\").classList.remove(\"open\");\r\n    };\r\n\r\n    async function loadArchivedStudents() {\r\n      const snap = await getDocs(collection(db, \"schools\", currentUser.uid, \"passedOutStudents\"));\r\n      allArchived = snap.docs.map((doc) => ({ id: doc.id, ...doc.data() }))\r\n        .sort((a, b) => Number(b.passoutYear || 0) - Number(a.passoutYear || 0) || String(a.name || \"\").localeCompare(String(b.name || \"\")));\r\n      filteredArchived = [...allArchived];\r\n      populateYears();\r\n      renderStudents();\r\n    }\r\n\r\n    onAuthStateChanged(auth, async (user) => {\r\n      if (!user) {\r\n        window.location.href = \"#/index.html\";\r\n        return;\r\n      }\r\n      currentUser = user;\r\n      try {\r\n        await loadArchivedStudents();\r\n      } catch (error) {\r\n        console.error(\"Error loading passed out students:\", error);\r\n        document.getElementById(\"studentsList\").innerHTML = `\r\n          <div class=\"empty\">\r\n            <div class=\"empty-icon\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"1.5\" stroke=\"currentColor\">\r\n                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126zM12 15.75h.007v.008H12v-.008z\" />\r\n              </svg>\r\n            </div>\r\n            Unable to load passed out students.\r\n          </div>\r\n        `;\r\n      }\r\n    });\r\n  </script>\r\n  <script type=\"module\" src=\"access-control.js\"></script>\r\n  <script src=\"schoolix-polish.js\" defer></script>\r\n  <script src=\"admin-shell.js?v=navbar-20260721\" defer></script>\r\n","styles":[{"tag":"style","attributes":{"id":"sxCriticalLoaderStyle"},"text":"\r\nhtml.sx-page-loading,\r\nhtml.sx-page-loading body {\r\n  min-height: 100%;\r\n  background: #f8fafc !important;\r\n}\r\nhtml.sx-page-loading body::before,\r\nhtml.sx-page-loading body::after {\r\n  visibility: hidden !important;\r\n}\r\nhtml.sx-page-loading body > :not(#sxPageLoader):not(script):not(style) {\r\n  visibility: hidden !important;\r\n}\r\n.sx-page-loader {\r\n  position: fixed;\r\n  inset: 0;\r\n  z-index: 2147482500;\r\n  display: flex;\r\n  align-items: stretch;\r\n  justify-content: stretch;\r\n  background: #f8fafc;\r\n  transition: opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1), visibility 0.25s ease;\r\n  overflow: hidden;\r\n}\r\n.sx-page-loader.is-hidden {\r\n  opacity: 0;\r\n  visibility: hidden;\r\n  pointer-events: none;\r\n}\r\n.sx-page-loader .dots-container {\r\n  position: fixed;\r\n  inset: 0;\r\n  display: block;\r\n  width: 100vw;\r\n  height: 100vh;\r\n  padding: 0;\r\n  margin: 0;\r\n  overflow: hidden;\r\n  background: #f8fafc;\r\n}\r\n.sx-page-loader .dots-container::before,\r\n.sx-page-loader .dots-container::after,\r\n.sx-page-loader .dot {\r\n  display: none !important;\r\n}\r\n"},{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-polish.css"},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"admin-shell.css?v=navbar-20260721"},"text":""}],"scripts":[{"attributes":{"id":"sxCriticalLoaderScript"},"text":"\r\n(function () {\r\n  var root = document.documentElement;\r\n  root.classList.add(\"sx-page-loading\");\r\n  window.SchoolixPageLoaderEarly = window.SchoolixPageLoaderEarly || { startedAt: Date.now() };\r\n\r\n  function markEarlyReady(reason) {\r\n    window.SchoolixPageLoaderEarly.ready = true;\r\n    window.SchoolixPageLoaderEarly.reason = reason || \"dom-ready\";\r\n    try {\r\n      window.dispatchEvent(new CustomEvent(\"schoolix:critical-load-ready\", { detail: window.SchoolixPageLoaderEarly }));\r\n    } catch (_) {}\r\n  }\r\n\r\n  function afterFirstPaint(reason) {\r\n    requestAnimationFrame(function () {\r\n      requestAnimationFrame(function () { markEarlyReady(reason); });\r\n    });\r\n  }\r\n\r\n  function emergencyHide() {\r\n    if (window.SchoolixPageLoader || !root.classList.contains(\"sx-page-loading\")) return;\r\n    root.classList.remove(\"sx-page-loading\");\r\n    root.classList.add(\"sx-page-loaded\");\r\n    var loader = document.getElementById(\"sxPageLoader\");\r\n    if (!loader) return;\r\n    loader.classList.add(\"is-hidden\");\r\n    setTimeout(function () { loader.remove(); }, 260);\r\n  }\r\n\r\n  if (document.readyState === \"loading\") {\r\n    document.addEventListener(\"DOMContentLoaded\", function () { afterFirstPaint(\"dom-ready\"); }, { once: true });\r\n  } else {\r\n    afterFirstPaint(document.readyState === \"complete\" ? \"document-complete\" : \"dom-ready\");\r\n  }\r\n  window.addEventListener(\"load\", function () { markEarlyReady(\"window-load\"); }, { once: true });\r\n  setTimeout(emergencyHide, 3200);\r\n}());\r\n"},{"attributes":{"type":"module"},"text":"\r\n    import { initializeApp } from \"./firebase-compat.js\";\r\n    import { getFirestore, collection, getDocs } from \"./firebase-compat.js\";\r\n    import { getAuth, onAuthStateChanged } from \"./firebase-compat.js\";\r\n\r\n    const firebaseConfig = {\r\n       apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n      authDomain: \"schoolix-48107.firebaseapp.com\",\r\n      projectId: \"schoolix-48107\",\r\n      storageBucket: \"schoolix-48107.firebasestorage.app\",\r\n      messagingSenderId: \"133937954491\",\r\n      appId: \"1:133937954491:web:69d8064422617eb8c4339e\",\r\n      measurementId: \"G-EG23XE5Q0Z\"\r\n    };\r\n\r\n    const app = initializeApp(firebaseConfig);\r\n    const db = getFirestore(app);\r\n    const auth = getAuth(app);\r\n    let currentUser = null;\r\n    let allArchived = [];\r\n    let filteredArchived = [];\r\n    let activeDetailStudent = null;\r\n\r\n    const esc = (value) => String(value ?? \"\").replace(/[&<>\"']/g, (char) => ({\r\n      \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\"\r\n    }[char]));\r\n    const val = (value) => value === undefined || value === null || value === \"\" ? \"N/A\" : value;\r\n    const phoneOf = (s = {}) => s.fatherPhone || s.fatherMobile || s.motherPhone || s.motherMobile || s.phone || \"\";\r\n    const finalClassOf = (s = {}) => [s.finalClass || s.class, s.finalSection || s.section].filter(Boolean).join(\"-\") || \"N/A\";\r\n    const recordCount = (s = {}, key) => Array.isArray(s.records?.[key]) ? s.records[key].length : 0;\r\n    const monthOrder = [\"January\", \"February\", \"March\", \"April\", \"May\", \"June\", \"July\", \"August\", \"September\", \"October\", \"November\", \"December\"];\r\n    const formatCurrency = (value = 0) => `₹${Number(value || 0).toLocaleString(\"en-IN\")}`;\r\n\r\n    function archiveStatus(student = {}) {\r\n      return student.status || (student.tcIssued ? \"TC Issued\" : \"Passed Out\");\r\n    }\r\n\r\n    function archiveStatusText(student = {}) {\r\n      const base = archiveStatus(student);\r\n      return student.tcIssued && base !== \"TC Issued\" ? `${base} + TC Issued` : base;\r\n    }\r\n\r\n    function archiveStatusPills(student = {}) {\r\n      const base = archiveStatus(student);\r\n      const academicLabel = base === \"TC Issued\" && !student.passoutYear ? \"TC Only\" : base;\r\n      const academicClass = academicLabel === \"Passed Out\" ? \"promoted\" : \"neutral\";\r\n      const tcLabel = student.tcIssued ? \"TC Issued\" : \"TC Not Issued\";\r\n      const tcClass = student.tcIssued ? \"tc\" : \"neutral\";\r\n      const checkIcon = `<svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2.5\" stroke=\"currentColor\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M4.5 12.75l6 6 9-13.5\" /></svg>`;\r\n      return `\r\n        <div class=\"status-panel\">\r\n          <div class=\"status-line\">\r\n            <span class=\"status-label\">Academic</span>\r\n            <span class=\"pill ${academicClass}\">${academicLabel === \"Passed Out\" ? checkIcon : \"\"}${esc(academicLabel)}</span>\r\n          </div>\r\n          <div class=\"status-line\">\r\n            <span class=\"status-label\">TC</span>\r\n            <span class=\"pill ${tcClass}\">${student.tcIssued ? checkIcon : \"\"}${esc(tcLabel)}</span>\r\n          </div>\r\n        </div>\r\n      `;\r\n    }\r\n\r\n    function toDate(value) {\r\n      if (!value) return null;\r\n      if (value?.toDate) return value.toDate();\r\n      if (value?.seconds) return new Date(value.seconds * 1000);\r\n      if (value instanceof Date) return value;\r\n      const date = new Date(value);\r\n      return Number.isNaN(date.getTime()) ? null : date;\r\n    }\r\n\r\n    function formatDate(value) {\r\n      const date = toDate(value);\r\n      return date ? date.toLocaleDateString(\"en-IN\", { day: \"2-digit\", month: \"short\", year: \"numeric\" }) : val(value);\r\n    }\r\n\r\n    function getMonthName(value) {\r\n      if (monthOrder.includes(value)) return value;\r\n      const date = toDate(value);\r\n      return date ? monthOrder[date.getMonth()] : \"Other\";\r\n    }\r\n\r\n    function getYearValue(value, fallback = \"\") {\r\n      const date = toDate(value);\r\n      if (date) return String(date.getFullYear());\r\n      const years = String(value || fallback || \"\").match(/\\b(20\\d{2}|19\\d{2})\\b/g);\r\n      return years?.length ? years[years.length - 1] : \"No Year\";\r\n    }\r\n\r\n    function getSessionLabel(record = {}, fallback = \"No Session\") {\r\n      return record.session || record.academicSession || record.currentYear || record.sessionName || record.sessionId || fallback;\r\n    }\r\n\r\n    function getFeeAmounts(fee = {}) {\r\n      const total = Number(fee.originalAmount ?? fee.amount ?? 0);\r\n      const applied = Array.isArray(fee.payments)\r\n        ? fee.payments.reduce((sum, payment) => sum + Number(payment.appliedAmount ?? payment.amount ?? 0), 0)\r\n        : Number(fee.totalPaidAmount ?? fee.paidAmount ?? 0);\r\n      const extra = Number(fee.totalExtraPaidAmount ?? fee.extraAmount ?? 0);\r\n      const collected = Number(fee.totalCollectedAmount ?? applied + extra);\r\n      const due = Number.isFinite(Number(fee.remainingAmount))\r\n        ? Number(fee.remainingAmount)\r\n        : Math.max(0, total - applied);\r\n      return { total, applied, extra, collected, due: Math.max(0, due) };\r\n    }\r\n\r\n    function statusClass(value = \"\") {\r\n      const text = String(value).toLowerCase();\r\n      if (text.includes(\"present\") || text === \"paid\") return \"paid present\";\r\n      if (text.includes(\"half\") || text.includes(\"partial\")) return \"partial half\";\r\n      if (text.includes(\"absent\") || text.includes(\"unpaid\") || text.includes(\"imposed\") || text.includes(\"pending\")) return \"due absent\";\r\n      return \"\";\r\n    }\r\n\r\n    function groupBy(records, getKey) {\r\n      return records.reduce((map, record) => {\r\n        const key = getKey(record);\r\n        if (!map.has(key)) map.set(key, []);\r\n        map.get(key).push(record);\r\n        return map;\r\n      }, new Map());\r\n    }\r\n\r\n    function sortMonthKeys(keys) {\r\n      return [...keys].sort((a, b) => {\r\n        const [yearA, monthA] = a.split(\"::\");\r\n        const [yearB, monthB] = b.split(\"::\");\r\n        const yearDiff = Number(yearB || 0) - Number(yearA || 0);\r\n        if (yearDiff) return yearDiff;\r\n        return monthOrder.indexOf(monthA) - monthOrder.indexOf(monthB);\r\n      });\r\n    }\r\n\r\n    function uniqueOptions(records, getKey) {\r\n      return [...new Set(records.map(getKey).filter(Boolean))];\r\n    }\r\n\r\n    function monthKeyForRecord(record = {}) {\r\n      const source = record.date || record.timestamp || record.createdAt || record.updatedAt || record.month;\r\n      return `${getYearValue(source, getSessionLabel(record))}::${getMonthName(record.month || source)}`;\r\n    }\r\n\r\n    function renderSelectOptions(values, placeholder) {\r\n      return `<option value=\"\">${esc(placeholder)}</option>${values.map((value) => `<option value=\"${esc(value)}\">${esc(value.replace(\"::\", \" - \"))}</option>`).join(\"\")}`;\r\n    }\r\n\r\n    function getReportTermKey(report = {}) {\r\n      return report.termLabel || report.term || report.termKey || report.examName || report.title || \"Untitled Term\";\r\n    }\r\n\r\n    function renderReportControls(type, student = {}) {\r\n      const records = Array.isArray(student.records?.[type]) ? student.records[type] : [];\r\n      if (!records.length) return '<div class=\"report-empty\">No archived records found for this student.</div>';\r\n      const sessions = uniqueOptions(records, getSessionLabel).sort();\r\n      if (type === \"reportCards\") {\r\n        const terms = uniqueOptions(records, getReportTermKey).sort();\r\n        return `\r\n          <div class=\"report-controls\">\r\n            <div class=\"filter-group\">\r\n              <label>Result Session</label>\r\n              <select id=\"${type}SessionFilter\" onchange=\"renderArchivedReport('${type}')\">\r\n                ${renderSelectOptions(sessions, \"Select session\")}\r\n              </select>\r\n            </div>\r\n            <div class=\"filter-group\">\r\n              <label>Result Term</label>\r\n              <select id=\"${type}TermFilter\" onchange=\"renderArchivedReport('${type}')\">\r\n                ${renderSelectOptions(terms, \"Select term\")}\r\n              </select>\r\n            </div>\r\n          </div>\r\n          <div id=\"${type}ReportOutput\" class=\"report-empty\">Select session and term to view result history.</div>\r\n        `;\r\n      }\r\n      const months = sortMonthKeys(uniqueOptions(records, monthKeyForRecord));\r\n      const title = type === \"attendance\" ? \"Attendance History\" : \"Payment History\";\r\n      return `\r\n        <div class=\"report-controls\">\r\n          <div class=\"filter-group\">\r\n            <label>${title} Session</label>\r\n            <select id=\"${type}SessionFilter\" onchange=\"renderArchivedReport('${type}')\">\r\n              ${renderSelectOptions(sessions, \"Select session\")}\r\n            </select>\r\n          </div>\r\n          <div class=\"filter-group\">\r\n            <label>${title} Month</label>\r\n            <select id=\"${type}MonthFilter\" onchange=\"renderArchivedReport('${type}')\">\r\n              ${renderSelectOptions(months, \"Select month\")}\r\n            </select>\r\n          </div>\r\n        </div>\r\n        <div id=\"${type}ReportOutput\" class=\"report-empty\">Select session and month to view ${title.toLowerCase()}.</div>\r\n      `;\r\n    }\r\n\r\n    window.renderArchivedReport = (type) => {\r\n      if (!activeDetailStudent) return;\r\n      const output = document.getElementById(`${type}ReportOutput`);\r\n      const selectedSession = document.getElementById(`${type}SessionFilter`)?.value || \"\";\r\n      if (type === \"reportCards\") {\r\n        const selectedTerm = document.getElementById(`${type}TermFilter`)?.value || \"\";\r\n        if (!output) return;\r\n        if (!selectedSession || !selectedTerm) {\r\n          output.className = \"report-empty\";\r\n          output.innerHTML = \"Select session and term to view result history.\";\r\n          return;\r\n        }\r\n        const records = (activeDetailStudent.records?.reportCards || []).filter((record) =>\r\n          getSessionLabel(record) === selectedSession && getReportTermKey(record) === selectedTerm\r\n        );\r\n        output.className = \"\";\r\n        output.innerHTML = renderResultTable(records);\r\n        return;\r\n      }\r\n      const selectedMonth = document.getElementById(`${type}MonthFilter`)?.value || \"\";\r\n      if (!output) return;\r\n      if (!selectedSession || !selectedMonth) {\r\n        output.className = \"report-empty\";\r\n        output.innerHTML = `Select session and month to view ${type === \"attendance\" ? \"attendance history\" : \"payment history\"}.`;\r\n        return;\r\n      }\r\n      const records = (activeDetailStudent.records?.[type] || []).filter((record) =>\r\n        getSessionLabel(record) === selectedSession && monthKeyForRecord(record) === selectedMonth\r\n      );\r\n      output.className = \"\";\r\n      output.innerHTML = type === \"attendance\" ? renderAttendanceTable(records, selectedMonth) : renderFeesTable(records, selectedMonth);\r\n    };\r\n\r\n    function renderAttendanceTable(records = [], selectedMonth = \"\") {\r\n      if (!records.length) return '<div class=\"report-empty\">No attendance found for selected session and month.</div>';\r\n      const [year, month] = selectedMonth.split(\"::\");\r\n      const sorted = records.sort((a, b) => (toDate(a.date || a.timestamp || a.createdAt) || 0) - (toDate(b.date || b.timestamp || b.createdAt) || 0));\r\n      const counts = sorted.reduce((summary, record) => {\r\n        const status = String(record.status || \"Not Marked\");\r\n        if (status === \"Present\") summary.present += 1;\r\n        else if (status === \"Absent\") summary.absent += 1;\r\n        else if (status === \"Half Day\") summary.half += 1;\r\n        else summary.other += 1;\r\n        return summary;\r\n      }, { present: 0, absent: 0, half: 0, other: 0 });\r\n      const marked = counts.present + counts.absent + counts.half + counts.other;\r\n      const percentage = marked ? Math.round(((counts.present + counts.half * 0.5) / marked) * 100) : 0;\r\n      return `\r\n        <div class=\"report-section\">\r\n          <div class=\"report-head\">\r\n            <span>${esc(month)} ${esc(year)}</span>\r\n            <span>Present ${counts.present} | Half ${counts.half} | Absent ${counts.absent} | Attendance ${percentage}%</span>\r\n          </div>\r\n          <table class=\"report-table\">\r\n            <thead>\r\n              <tr><th>Date</th><th>Status</th><th>Class</th><th>Marked By</th><th>Remarks</th></tr>\r\n            </thead>\r\n            <tbody>\r\n              ${sorted.map((record) => `\r\n                <tr>\r\n                  <td>${esc(formatDate(record.date || record.timestamp || record.createdAt))}</td>\r\n                  <td><span class=\"status-chip ${statusClass(record.status)}\">${esc(record.status || \"Not Marked\")}</span></td>\r\n                  <td>${esc([record.class, record.section].filter(Boolean).join(\"-\") || \"N/A\")}</td>\r\n                  <td>${esc(record.markedBy || record.markedByRole || \"N/A\")}</td>\r\n                  <td>${esc(record.remarks || record.note || \"\")}</td>\r\n                </tr>\r\n              `).join(\"\")}\r\n            </tbody>\r\n          </table>\r\n        </div>\r\n      `;\r\n    }\r\n\r\n    function renderFeesTable(records = [], selectedMonth = \"\") {\r\n      if (!records.length) return '<div class=\"report-empty\">No fee/payment history found for selected session and month.</div>';\r\n      const [year, month] = selectedMonth.split(\"::\");\r\n      const sorted = records.sort((a, b) => (toDate(a.date || a.createdAt) || 0) - (toDate(b.date || b.createdAt) || 0));\r\n      const totals = sorted.reduce((sum, fee) => {\r\n        const amount = getFeeAmounts(fee);\r\n        sum.assigned += amount.total;\r\n        sum.applied += amount.applied;\r\n        sum.extra += amount.extra;\r\n        sum.due += amount.due;\r\n        return sum;\r\n      }, { assigned: 0, applied: 0, extra: 0, due: 0 });\r\n      return `\r\n        <div class=\"report-section\">\r\n          <div class=\"report-head\">\r\n            <span>${esc(month)} ${esc(year)}</span>\r\n            <span>Assigned ${formatCurrency(totals.assigned)} | Paid ${formatCurrency(totals.applied)} | Due ${formatCurrency(totals.due)}</span>\r\n          </div>\r\n          <table class=\"report-table\">\r\n            <thead>\r\n              <tr><th>Month</th><th>Assigned</th><th>Paid / Applied</th><th>Extra</th><th>Due</th><th>Status</th><th>Payments</th></tr>\r\n            </thead>\r\n            <tbody>\r\n              ${sorted.map((fee) => {\r\n                const amount = getFeeAmounts(fee);\r\n                const payments = Array.isArray(fee.payments) && fee.payments.length\r\n                  ? fee.payments.map((payment) => `${esc(formatDate(payment.date))}: ${formatCurrency(payment.receivedAmount ?? payment.fullAmount ?? payment.amount ?? 0)} received, ${formatCurrency(payment.appliedAmount ?? payment.amount ?? 0)} applied`).join(\"<br>\")\r\n                  : \"No payment history\";\r\n                return `\r\n                  <tr>\r\n                    <td>${esc(fee.month || \"N/A\")}<br><small style=\"color:var(--slate-500)\">${esc(formatDate(fee.date || fee.createdAt || fee.updatedAt))}</small></td>\r\n                    <td class=\"money\">${formatCurrency(amount.total)}</td>\r\n                    <td class=\"money\">${formatCurrency(amount.applied)}</td>\r\n                    <td class=\"money\">${formatCurrency(amount.extra)}</td>\r\n                    <td class=\"money\">${formatCurrency(amount.due)}</td>\r\n                    <td><span class=\"status-chip ${statusClass(fee.status)}\">${esc(fee.status || \"Pending\")}</span></td>\r\n                    <td>${payments}</td>\r\n                  </tr>\r\n                `;\r\n              }).join(\"\")}\r\n            </tbody>\r\n          </table>\r\n        </div>\r\n      `;\r\n    }\r\n\r\n    function renderResultTable(records = []) {\r\n      if (!records.length) return '<div class=\"report-empty\">No result/report card found for selected session and term.</div>';\r\n      const sorted = records.sort((a, b) => (toDate(b.createdAt || b.generatedAt || b.updatedAt) || 0) - (toDate(a.createdAt || a.generatedAt || a.updatedAt) || 0));\r\n      return sorted.map((report) => {\r\n        const subjects = Array.isArray(report.subjects) ? report.subjects : [];\r\n        const totalObtained = report.totalMarks ?? report.obtainedMarks ?? subjects.reduce((sum, sub) => sum + Number(sub.obtained ?? sub.obtainedMarks ?? sub.marks ?? 0), 0);\r\n        const totalMax = report.totalMaxMarks ?? report.maxMarks ?? subjects.reduce((sum, sub) => sum + Number(sub.maxMarks ?? sub.totalMarks ?? 0), 0);\r\n        const percentage = report.percentage ?? (Number(totalMax) ? ((Number(totalObtained) / Number(totalMax)) * 100).toFixed(2) : \"\");\r\n        return `\r\n          <div class=\"report-section\">\r\n            <div class=\"report-head\">\r\n              <span>${esc(getReportTermKey(report))}</span>\r\n              <span>Percentage ${esc(percentage || \"N/A\")}% | Grade ${esc(report.grade || \"N/A\")}</span>\r\n            </div>\r\n            <div class=\"detail-grid\" style=\"padding:16px;background:var(--slate-50)\">\r\n              ${field(\"Session\", getSessionLabel(report))}\r\n              ${field(\"Generated\", formatDate(report.createdAt || report.generatedAt || report.updatedAt))}\r\n              ${field(\"Total Marks\", `${totalObtained || \"N/A\"} / ${totalMax || \"N/A\"}`)}\r\n              ${field(\"Rank\", report.rank)}\r\n              ${field(\"Remarks\", report.remarks || report.teacherRemarks || report.resultRemarks)}\r\n            </div>\r\n            <table class=\"report-table\">\r\n              <thead>\r\n                <tr><th>Subject</th><th>Obtained</th><th>Max</th><th>Grade</th><th>Remarks</th></tr>\r\n              </thead>\r\n              <tbody>\r\n                ${subjects.length ? subjects.map((sub) => `\r\n                  <tr>\r\n                    <td>${esc(sub.name || sub.subject || \"Subject\")}</td>\r\n                    <td>${esc(sub.obtained ?? sub.obtainedMarks ?? sub.marks ?? \"N/A\")}</td>\r\n                    <td>${esc(sub.maxMarks ?? sub.totalMarks ?? \"N/A\")}</td>\r\n                    <td>${esc(sub.grade || \"N/A\")}</td>\r\n                    <td>${esc(sub.remarks || \"\")}</td>\r\n                  </tr>\r\n                `).join(\"\") : '<tr><td colspan=\"5\" style=\"text-align:center;color:var(--slate-500)\">No subject details saved in this report.</td></tr>'}\r\n              </tbody>\r\n            </table>\r\n          </div>\r\n        `;\r\n      }).join(\"\");\r\n    }\r\n\r\n    function searchableText(student = {}) {\r\n      return [\r\n        student.name, student.studentName, student.studentId, student.roll, student.email,\r\n        student.parentEmail, student.father, student.mother, student.fatherPhone,\r\n        student.motherPhone, student.phone, student.passoutYear, student.tcNumber,\r\n        student.srNumber, student.category, student.gender, student.aadharNumber,\r\n        student.archiveReason, archiveStatusText(student), student.tcIssued ? \"tc issued\" : \"tc not issued\", finalClassOf(student)\r\n      ].join(\" \").toLowerCase();\r\n    }\r\n\r\n    function populateYears() {\r\n      const select = document.getElementById(\"yearFilter\");\r\n      const years = [...new Set(allArchived.map((s) => s.passoutYear).filter(Boolean))]\r\n        .sort((a, b) => Number(b) - Number(a));\r\n      select.innerHTML = '<option value=\"\">All Years</option>' + years.map((year) => `<option value=\"${esc(year)}\">${esc(year)}</option>`).join(\"\");\r\n    }\r\n\r\n    function updateStats(students = filteredArchived) {\r\n      const years = new Set(students.map((s) => s.passoutYear).filter(Boolean));\r\n      const tc = students.filter((s) => s.tcIssued || archiveStatus(s) === \"TC Issued\").length;\r\n      const passed = students.filter((s) => archiveStatus(s) === \"Passed Out\").length;\r\n      document.getElementById(\"statsGrid\").innerHTML = `\r\n        <div class=\"stat\">\r\n          <div class=\"stat-header\">\r\n            <div class=\"stat-icon blue\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M15 19.128a9.38 9.38 0 002.625.372 9.337 9.337 0 004.121-.952 4.125 4.125 0 00-7.533-2.493M15 19.128v-.003c0-1.113-.285-2.16-.786-3.07M15 19.128v.106A12.318 12.318 0 018.624 21c-2.331 0-4.512-.645-6.374-1.766l-.001-.109a6.375 6.375 0 0111.964-3.07M12 6.375a3.375 3.375 0 11-6.75 0 3.375 3.375 0 016.75 0zm8.25 2.25a2.625 2.625 0 11-5.25 0 2.625 2.625 0 015.25 0z\" />\r\n              </svg>\r\n            </div>\r\n          </div>\r\n          <strong>${students.length}</strong>\r\n          <span>Visible Records</span>\r\n        </div>\r\n        <div class=\"stat\">\r\n          <div class=\"stat-header\">\r\n            <div class=\"stat-icon green\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 012.25-2.25h13.5A2.25 2.25 0 0121 7.5v11.25m-18 0A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75m-18 0v-7.5A2.25 2.25 0 015.25 9h13.5A2.25 2.25 0 0121 11.25v7.5\" />\r\n              </svg>\r\n            </div>\r\n          </div>\r\n          <strong>${years.size}</strong>\r\n          <span>Passout Years</span>\r\n        </div>\r\n        <div class=\"stat\">\r\n          <div class=\"stat-header\">\r\n            <div class=\"stat-icon orange\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M4.26 10.147a60.436 60.436 0 00-.491 6.347A48.627 48.627 0 0112 20.904a48.627 48.627 0 018.232-4.41 60.46 60.46 0 00-.491-6.347m-15.482 0a50.57 50.57 0 00-2.658-.813A59.905 59.905 0 0112 3.493a59.902 59.902 0 0110.399 5.84c-.896.248-1.783.52-2.658.814m-15.482 0A50.697 50.697 0 0112 13.489a50.702 50.702 0 017.74-3.342\" />\r\n              </svg>\r\n            </div>\r\n          </div>\r\n          <strong>${passed}</strong>\r\n          <span>Class 12 Passout</span>\r\n        </div>\r\n        <div class=\"stat\">\r\n          <div class=\"stat-header\">\r\n            <div class=\"stat-icon red\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m0 12.75h7.5m-7.5 3H12M10.5 2.25H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z\" />\r\n              </svg>\r\n            </div>\r\n          </div>\r\n          <strong>${tc}</strong>\r\n          <span>TC Issued</span>\r\n        </div>\r\n      `;\r\n    }\r\n\r\n    function renderStudents(students = filteredArchived) {\r\n      updateStats(students);\r\n      const target = document.getElementById(\"studentsList\");\r\n      if (!students.length) {\r\n        target.innerHTML = `\r\n          <div class=\"empty\">\r\n            <div class=\"empty-icon\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"1.5\" stroke=\"currentColor\">\r\n                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M20.25 7.5l-.625 10.632a2.25 2.25 0 01-2.247 2.118H6.622a2.25 2.25 0 01-2.247-2.118L3.75 7.5m6 4.125l2.25 2.25m0 0l2.25 2.25M12 13.875l2.25-2.25M12 13.875l-2.25 2.25M3.375 7.5h17.25c.621 0 1.125-.504 1.125-1.125v-1.5c0-.621-.504-1.125-1.125-1.125H3.375c-.621 0-1.125.504-1.125 1.125v1.5c0 .621.504 1.125 1.125 1.125z\" />\r\n              </svg>\r\n            </div>\r\n            No archived students found for selected filters.\r\n          </div>\r\n        `;\r\n        return;\r\n      }\r\n      target.innerHTML = students.map((s) => {\r\n        return `\r\n          <div class=\"row\">\r\n            <div class=\"student-cell\" data-label=\"Student\">\r\n              <div class=\"avatar\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"1.5\" stroke=\"currentColor\">\r\n                  <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M15.75 6a3.75 3.75 0 11-7.5 0 3.75 3.75 0 017.5 0zM4.501 20.118a7.5 7.5 0 0114.998 0A17.933 17.933 0 0112 21.75c-2.676 0-5.216-.584-7.499-1.632z\" />\r\n                </svg>\r\n              </div>\r\n              <div>\r\n                <div class=\"name\">${esc(s.name || s.studentName || \"N/A\")}</div>\r\n                <div class=\"muted\">\r\n                  <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n                    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M21.75 6.75v10.5a2.25 2.25 0 01-2.25 2.25h-15a2.25 2.25 0 01-2.25-2.25V6.75m19.5 0A2.25 2.25 0 0019.5 4.5h-15a2.25 2.25 0 00-2.25 2.25m19.5 0v.243a2.25 2.25 0 01-1.07 1.916l-7.5 4.615a2.25 2.25 0 01-2.36 0L3.32 8.91a2.25 2.25 0 01-1.07-1.916V6.75\" />\r\n                  </svg>\r\n                  ${esc(s.email || s.parentEmail || \"No email\")}\r\n                </div>\r\n              </div>\r\n            </div>\r\n            <div class=\"id-cell\" data-label=\"ID / Roll\">\r\n              <span class=\"id-value\">${esc(s.studentId || s.id || \"N/A\")}</span>\r\n              <span class=\"roll-value\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n                  <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M5.25 8.25h15m-16.5 7.5h15m-1.8-13.5l-3.9 19.5m-2.1-19.5l-3.9 19.5\" />\r\n                </svg>\r\n                Roll ${esc(s.roll || \"-\")}\r\n              </span>\r\n            </div>\r\n            <div class=\"id-cell\" data-label=\"SR No.\">\r\n              <span class=\"id-value\">${esc(s.srNumber || \"N/A\")}</span>\r\n              <span class=\"roll-value\">School record</span>\r\n            </div>\r\n            <div data-label=\"Final Class\">\r\n              <span class=\"class-badge\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n                  <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M4.26 10.147a60.436 60.436 0 00-.491 6.347A48.627 48.627 0 0112 20.904a48.627 48.627 0 018.232-4.41 60.46 60.46 0 00-.491-6.347m-15.482 0a50.57 50.57 0 00-2.658-.813A59.905 59.905 0 0112 3.493a59.902 59.902 0 0110.399 5.84c-.896.248-1.783.52-2.658.814m-15.482 0A50.697 50.697 0 0112 13.489a50.702 50.702 0 017.74-3.342\" />\r\n                </svg>\r\n                ${esc(finalClassOf(s))}\r\n              </span>\r\n            </div>\r\n            <div data-label=\"Phone\">\r\n              <span class=\"phone-value\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n                  <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M2.25 6.75c0 8.284 6.716 15 15 15h2.25a2.25 2.25 0 002.25-2.25v-1.372c0-.516-.351-.966-.852-1.091l-4.423-1.106c-.44-.11-.902.055-1.173.417l-.97 1.293c-.282.376-.769.542-1.21.38a12.035 12.035 0 01-7.143-7.143c-.162-.441.004-.928.38-1.21l1.293-.97c.363-.271.527-.734.417-1.173L6.963 3.102a1.125 1.125 0 00-1.091-.852H4.5A2.25 2.25 0 002.25 4.5v2.25z\" />\r\n                </svg>\r\n                ${esc(phoneOf(s) || \"N/A\")}\r\n              </span>\r\n            </div>\r\n            <div data-label=\"Year\">\r\n              <span class=\"year-badge\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n                  <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 012.25-2.25h13.5A2.25 2.25 0 0121 7.5v11.25m-18 0A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75m-18 0v-7.5A2.25 2.25 0 015.25 9h13.5A2.25 2.25 0 0121 11.25v7.5\" />\r\n                </svg>\r\n                ${esc(s.passoutYear || \"N/A\")}\r\n              </span>\r\n            </div>\r\n            <div data-label=\"Status\">${archiveStatusPills(s)}</div>\r\n            <div data-label=\"Action\">\r\n              <button class=\"btn-view\" onclick=\"showDetails('${esc(s.id)}')\">\r\n                <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n                  <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M2.036 12.322a1.012 1.012 0 010-.639C3.423 7.51 7.36 4.5 12 4.5c4.638 0 8.573 3.007 9.963 7.178.07.207.07.431 0 .639C20.577 16.49 16.64 19.5 12 19.5c-4.638 0-8.573-3.007-9.963-7.178z\" />\r\n                  <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M15 12a3 3 0 11-6 0 3 3 0 016 0z\" />\r\n                </svg>\r\n                View\r\n              </button>\r\n            </div>\r\n          </div>\r\n        `;\r\n      }).join(\"\");\r\n    }\r\n\r\n    window.applyFilters = () => {\r\n      const queryText = document.getElementById(\"searchInput\").value.trim().toLowerCase();\r\n      const year = document.getElementById(\"yearFilter\").value;\r\n      const status = document.getElementById(\"statusFilter\").value;\r\n      filteredArchived = allArchived.filter((student) => {\r\n        const actualStatus = archiveStatus(student);\r\n        const matchesSearch = !queryText || searchableText(student).includes(queryText);\r\n        const matchesYear = !year || String(student.passoutYear || \"\") === year;\r\n        const matchesStatus = !status || actualStatus === status || (status === \"TC Issued\" && student.tcIssued);\r\n        return matchesSearch && matchesYear && matchesStatus;\r\n      });\r\n      renderStudents(filteredArchived);\r\n    };\r\n\r\n    window.resetFilters = () => {\r\n      document.getElementById(\"searchInput\").value = \"\";\r\n      document.getElementById(\"yearFilter\").value = \"\";\r\n      document.getElementById(\"statusFilter\").value = \"\";\r\n      window.applyFilters();\r\n    };\r\n\r\n    function field(label, value, icon = \"\") {\r\n      return `<div class=\"field\"><span>${icon}${esc(label)}</span><strong>${esc(val(value))}</strong></div>`;\r\n    }\r\n\r\n    window.showDetails = (id) => {\r\n      const student = allArchived.find((entry) => entry.id === id);\r\n      if (!student) return;\r\n      activeDetailStudent = student;\r\n      const tc = student.transferCertificate || {};\r\n      document.getElementById(\"modalTitle\").innerHTML = `\r\n        <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n          <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M15.75 6a3.75 3.75 0 11-7.5 0 3.75 3.75 0 017.5 0zM4.501 20.118a7.5 7.5 0 0114.998 0A17.933 17.933 0 0112 21.75c-2.676 0-5.216-.584-7.499-1.632z\" />\r\n        </svg>\r\n        ${esc(student.name || student.studentName || \"Student\")} (${esc(student.passoutYear || \"N/A\")})\r\n      `;\r\n      document.getElementById(\"modalBody\").innerHTML = `\r\n        <div class=\"detail-grid\">\r\n          ${field(\"Name\", student.name || student.studentName)}\r\n          ${field(\"Student ID\", student.studentId)}\r\n          ${field(\"SR Number\", student.srNumber)}\r\n          ${field(\"Roll\", student.roll)}\r\n          ${field(\"Final Class\", finalClassOf(student))}\r\n          ${field(\"Passout Year\", student.passoutYear)}\r\n          ${field(\"Academic Status\", archiveStatus(student))}\r\n          ${field(\"TC Status\", student.tcIssued ? \"TC Issued\" : \"TC Not Issued\")}\r\n          ${field(\"Archive Reason\", student.archiveReason)}\r\n          ${field(\"Result %\", student.resultPercentage)}\r\n          ${field(\"Gender\", student.gender)}\r\n          ${field(\"Category\", student.category)}\r\n          ${field(\"Blood Group\", student.bloodGroup)}\r\n          ${field(\"Religion\", student.religion)}\r\n          ${field(\"Previous School\", student.previousSchool)}\r\n          ${field(\"Father\", student.father)}\r\n          ${field(\"Father Phone\", student.fatherPhone || student.fatherMobile)}\r\n          ${field(\"Father Email\", student.fatherEmail)}\r\n          ${field(\"Mother\", student.mother)}\r\n          ${field(\"Mother Phone\", student.motherPhone || student.motherMobile)}\r\n          ${field(\"Mother Email\", student.motherEmail)}\r\n          ${field(\"Phone\", student.phone)}\r\n          ${field(\"Email\", student.email)}\r\n          ${field(\"Parent Email\", student.parentEmail || student.fatherEmail || student.motherEmail)}\r\n          ${field(\"Admission Year\", student.yearOfAdmission)}\r\n          ${field(\"Admission Date\", student.admissionDate || student.dateOfAdmission)}\r\n          ${field(\"Current/Archive Session\", student.currentYear || student.academicSession || student.session)}\r\n          ${field(\"DOB\", student.dob)}\r\n          ${field(\"Aadhaar\", student.aadharNumber)}\r\n          ${field(\"Address\", student.address)}\r\n          ${field(\"Documents\", student.documentList || student.documents)}\r\n          ${field(\"Photo URL\", student.photoUrl || student.imageUrl || student.profilePhotoUrl)}\r\n        </div>\r\n        <h3 class=\"section-title\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M19.5 14.25v-2.625a3.375 3.375 0 00-3.375-3.375h-1.5A1.125 1.125 0 0113.5 7.125v-1.5a3.375 3.375 0 00-3.375-3.375H8.25m0 12.75h7.5m-7.5 3H12M10.5 2.25H5.625c-.621 0-1.125.504-1.125 1.125v17.25c0 .621.504 1.125 1.125 1.125h12.75c.621 0 1.125-.504 1.125-1.125V11.25a9 9 0 00-9-9z\" />\r\n          </svg>\r\n          Transfer Certificate\r\n        </h3>\r\n        <div class=\"detail-grid\">\r\n          ${field(\"TC Number\", student.tcNumber || tc.tcNumber)}\r\n          ${field(\"Leaving Date\", tc.leavingDate)}\r\n          ${field(\"Reason\", tc.reason)}\r\n          ${field(\"Conduct\", tc.conduct)}\r\n        </div>\r\n        <h3 class=\"section-title\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M3.75 9.776c.112-.017.227-.026.344-.026h15.812c.117 0 .232.009.344.026m-16.5 0a2.25 2.25 0 00-1.883 2.542l.857 6a2.25 2.25 0 002.227 1.932H19.05a2.25 2.25 0 002.227-1.932l.857-6a2.25 2.25 0 00-1.883-2.542m-16.5 0V6A2.25 2.25 0 016 3.75h3.879a1.5 1.5 0 011.06.44l2.122 2.12a1.5 1.5 0 001.06.44H18A2.25 2.25 0 0120.25 9v.776\" />\r\n          </svg>\r\n          Saved Record Counts\r\n        </h3>\r\n        <div class=\"detail-grid\">\r\n          ${field(\"Attendance Records\", recordCount(student, \"attendance\"))}\r\n          ${field(\"Fee Records\", recordCount(student, \"fees\"))}\r\n          ${field(\"Report Cards\", recordCount(student, \"reportCards\"))}\r\n        </div>\r\n        <h3 class=\"section-title\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z\" />\r\n          </svg>\r\n          Attendance History\r\n        </h3>\r\n        ${renderReportControls(\"attendance\", student)}\r\n        <h3 class=\"section-title\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M2.25 18.75a60.07 60.07 0 0115.797 2.101c.727.198 1.453-.342 1.453-1.096V18.75M3.75 4.5v.75A.75.75 0 013 6h-.75m0 0v-.375c0-.621.504-1.125 1.125-1.125H20.25M2.25 6v9m18-10.5v.75c0 .414.336.75.75.75h.75m-1.5-1.5h.375c.621 0 1.125.504 1.125 1.125v9.75c0 .621-.504 1.125-1.125 1.125h-.375m1.5-1.5H21a.75.75 0 00-.75.75v.75m0 0H3.75m0 0h-.375a1.125 1.125 0 01-1.125-1.125V15m1.5 1.5v-.75A.75.75 0 003 15h-.75M15 10.5a3 3 0 11-6 0 3 3 0 016 0zm3 0h.008v.008H18V10.5zm-12 0h.008v.008H6V10.5z\" />\r\n          </svg>\r\n          Payment History\r\n        </h3>\r\n        ${renderReportControls(\"fees\", student)}\r\n        <h3 class=\"section-title\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\">\r\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M4.26 10.147a60.436 60.436 0 00-.491 6.347A48.627 48.627 0 0112 20.904a48.627 48.627 0 018.232-4.41 60.46 60.46 0 00-.491-6.347m-15.482 0a50.57 50.57 0 00-2.658-.813A59.905 59.905 0 0112 3.493a59.902 59.902 0 0110.399 5.84c-.896.248-1.783.52-2.658.814m-15.482 0A50.697 50.697 0 0112 13.489a50.702 50.702 0 017.74-3.342\" />\r\n          </svg>\r\n          Result History\r\n        </h3>\r\n        ${renderReportControls(\"reportCards\", student)}\r\n      `;\r\n      document.getElementById(\"detailModal\").classList.add(\"open\");\r\n    };\r\n\r\n    window.closeDetails = () => {\r\n      activeDetailStudent = null;\r\n      document.getElementById(\"detailModal\").classList.remove(\"open\");\r\n    };\r\n\r\n    async function loadArchivedStudents() {\r\n      const snap = await getDocs(collection(db, \"schools\", currentUser.uid, \"passedOutStudents\"));\r\n      allArchived = snap.docs.map((doc) => ({ id: doc.id, ...doc.data() }))\r\n        .sort((a, b) => Number(b.passoutYear || 0) - Number(a.passoutYear || 0) || String(a.name || \"\").localeCompare(String(b.name || \"\")));\r\n      filteredArchived = [...allArchived];\r\n      populateYears();\r\n      renderStudents();\r\n    }\r\n\r\n    onAuthStateChanged(auth, async (user) => {\r\n      if (!user) {\r\n        window.location.href = \"#/index.html\";\r\n        return;\r\n      }\r\n      currentUser = user;\r\n      try {\r\n        await loadArchivedStudents();\r\n      } catch (error) {\r\n        console.error(\"Error loading passed out students:\", error);\r\n        document.getElementById(\"studentsList\").innerHTML = `\r\n          <div class=\"empty\">\r\n            <div class=\"empty-icon\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"1.5\" stroke=\"currentColor\">\r\n                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126zM12 15.75h.007v.008H12v-.008z\" />\r\n              </svg>\r\n            </div>\r\n            Unable to load passed out students.\r\n          </div>\r\n        `;\r\n      }\r\n    });\r\n  "},{"attributes":{"type":"module","src":"access-control.js"},"text":""},{"attributes":{"src":"schoolix-polish.js"},"text":""},{"attributes":{"src":"admin-shell.js?v=navbar-20260721"},"text":""}]};
